mapper.select:
SELECT COALESCE(MAX(priority), -1) + 1
FROM action_plans
WHERE goal_id = #{goal_id} AND user_id = #{user_id} AND delete_flg = 0;

mapper.update:
UPDATE action_plans
SET title = #{title},
    status = #{status}
WHERE id = #{id} AND user_id = #{user_id};

UPDATE action_plans
SET priority = #{priority}
WHERE id = #{id} AND user_id = #{user_id};

UPDATE action_plans
SET delete_flg = 1
WHERE id = #{id} AND user_id = #{user_id};
